	scanf("%d%d", &n, &s);
	for(int i = 1; i <= n; i++) {
		scanf("%d%d", &plane[i].h, &plane[i].m);
	}
	sort(plane + 1, plane + 1 + n, cmp);
	if(cal(plane[1]) >= s + 1) {
		printf("0 0");
		return 0;
	}
	for(int i = 1; i <= n; i++) {
		if(cal(plane[i+1]) - cal(plane[i]) >= 2 * s + 2) {
