inline void read(ll &x)
{
	x = 0;
	char ch = getchar();
	while(ch < '0' || ch > '9')
		ch = getchar();
	while(ch >= '0' && ch <= '9')
	{
		x = x * 10 + (ch ^ 48);
		ch = getchar();
	}
}
inline void write(ll x)
{
	if(x)
	{
		write(x / 10);
		putchar(x % 10 ^ 48);
	}
}
int main()
{
	ll n, m;
	read(n), read(m);
	for(ll i = 1; i <= n; ++ i)
		read(A[i]);
	ll Cnt = 0, F = 1ll;
	for(ll i = 1; i <= m; ++ i)
	{
		ll x;
		read(x);
		while(x - Cnt > A[F])
			Cnt += A[F], ++ F;
		write(F);
		putchar(' ');
		write(x - Cnt);
		puts("");
	}
	return 0;
}

